	set retStr=""
	if ((ncid="") || ($ISVALIDNUM(ncid)'="1")){
		quit retStr
	}
 	set retStr=..getRepByNcidFromCache(ncid, context)
	$$$TRACE("Cach returned rep: " _ retStr)
	if (retStr'="") {
		quit retStr
	}
	set newHddObj = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.HddObject).%New()
	set reqObj = ##class(IHC.ITF.ITFCOMMON.HDD.Interface.RepLookupRequest).%New()
	set reqObj.listOfHddRepObj = ##class(%ListOfObjects).%New()
	set newHddObj.NCID = ncid
	set newHddObj.Context = context
	Do reqObj.listOfHddRepObj.Insert(newHddObj)
    $$$TRACE("########Call HDD lookup for rep of : " _ ncid)
    set tStatus=process.SendRequestSync(hddOp,reqObj,.hddRepResponse)
    if ('tStatus) {
      $$$TRACE("Web service returned ERROR: "_$System.Status.GetOneStatusText(tStatus,1))
      $$$ThrowOnError(tStatus)
    }
    else { 
      set repObj = hddRepResponse.listOfHDDobj.GetAt(1)
      if ( repObj'="") {
	     If repObj.Rep["ERROR:"{
		    $$$TRACE("Web service returned: "_repObj.Rep)
	     }
	     else {
  	        set retStr = repObj.Rep
            $$$TRACE("Web service returned Rep: "_retStr_" for ncid: " _ ncid)
	     }
      }
    }

	return retStr

